    atkToken: tokenValue,
    wycToken: tokenValue,
    tjToken: tokenValue,
    dxToken: tokenValue,
    tokenParam: "_ff",
    path: path,
    fullUrl: fullUrl,
    timeKey: '',
    kV: '',
    config: {}
