function detectBundleFromScript(scriptText) {
  if (!vm) {
    return null;
  }
  let targetBundleUrl = null;
  const mockWindow = {
    XMLHttpRequest: function() {
      return {
        open: function(_method, url) { targetBundleUrl = url; },
        send: function() {}
      };
    },
    document: {
      createElement: () => ({ setAttribute: () => {}, appendChild: () => {} }),
      head: { appendChild: () => {} }
    },
    location: { href: 'https://www.korail.com/ticket/login' }
  };
  mockWindow.window = mockWindow;
  mockWindow.self = mockWindow;
  try {
    vm.runInContext(scriptText, vm.createContext(mockWindow));
  } catch (_) {}
  return targetBundleUrl;
}

if (typeof module !== 'undefined' && module.exports) {
  module.exports = { generateWebDynaPathToken, detectBundleFromScript };
}
if (typeof globalThis !== 'undefined') {
  globalThis.generateWebDynaPathToken = generateWebDynaPathToken;
  globalThis.detectBundleFromScript = detectBundleFromScript;
}

if (typeof process !== 'undefined' && process.argv && require.main === module) {
  const args = process.argv.slice(2);
  let seed = '';
  let url = '/classes/com.korail.mobile.certification.TicketReservation';
  let prefix = null;
  let body = '';
  let profile = {};
  let detectScript = null;

  for (let index = 0; index < args.length; index += 1) {
    if (args[index] === '--seed' && args[index + 1]) {
      seed = args[++index];
    } else if (args[index] === '--url' && args[index + 1]) {
      url = args[++index];
    } else if (args[index] === '--prefix' && args[index + 1]) {
      prefix = args[++index];
    } else if (args[index] === '--body' && args[index + 1]) {
      body = args[++index];
    } else if (args[index] === '--profile' && args[index + 1]) {
      profile = JSON.parse(args[++index]);
    } else if (args[index] === '--detect-bundle' && args[index + 1]) {
      detectScript = args[++index];
    }
  }

  if (detectScript !== null) {
    process.stdout.write(JSON.stringify({ bundleUrl: detectBundleFromScript(detectScript) }));
    process.exit(0);
  }
  if (!seed) {
    console.error('Error: --seed argument is required');
    process.exit(1);
  }

  try {
    const result = generateWebDynaPathToken({ seed, url, prefix, body, profile });
    process.stdout.write(JSON.stringify(result));
  } catch (error) {
    console.error('Error generating token:', error && error.message ? error.message : error);
    process.exit(1);
  }
}
